export const formalCorpus: FormalRow[] = [...dfrlResults, ...dhContracts];

export const proofs: ProofRow[] = formalCorpus.map((row) => ({
  code: row.code,
  name: row.name,
  domain: row.domain,
  status:
    row.classification === "AUTHORED_MODEL" || row.classification === "DH_FORMAL_CONTRACT"
      ? "VERIFIED"
      : "FAMILY_VARIANT",
  result: row.result,
  bundle: `PB-${row.code}`,
  classification: row.classification,
  corpus: row.corpus,
}));

